package com.fileservice

import io.grpc.stub.StreamObserver
import java.util.concurrent.{ConcurrentHashMap, atomic}
import scala.collection.mutable
import java.security.MessageDigest
import java.nio.file.{Files, Paths, Path}
import java.util.UUID

// Proto-generated stubs (simplified)
case class UploadChunk(sessionId: String, data: Array[Byte], offset: Long, isFinal: Boolean)
case class UploadResponse(status: String, bytesWritten: Long)
case class QuotaInfo(used: Long, limit: Long)

trait UploadServiceGrpc {
  def streamUpload(responseObserver: StreamObserver[UploadResponse]): StreamObserver[UploadChunk]
}

class QuotaManager {
  private val quotas = new ConcurrentHashMap[String, atomic.AtomicLong]()
  private val limits = new ConcurrentHashMap[String, Long]()

  def initialize(userId: String, limit: Long): Unit = {
    quotas.putIfAbsent(userId, new atomic.AtomicLong(0L))
    limits.putIfAbsent(userId, limit)
  }

  def getUsed(userId: String): Long = quotas.get(userId).get()
  def getLimit(userId: String): Long = limits.getOrDefault(userId, 0L)

  def tryReserve(userId: String, amount: Long): Boolean = {
    val current = quotas.get(userId)
    val limit = limits.getOrDefault(userId, 0L)
    if (current == null) return false
    // Check if reservation would exceed quota
    if (current.get() + amount <= limit) {
      true
    } else {
      false
    }
  }

  def commit(userId: String, amount: Long): Unit = {
    val current = quotas.get(userId)
    if (current != null) current.addAndGet(amount)
  }

  def rollback(userId: String, amount: Long): Unit = {
    val current = quotas.get(userId)
    if (current != null) current.addAndGet(-amount)
  }
}

class SessionState(
  val userId: String,
  val uploadId: String,
  val targetPath: Path
) {
  var totalReceived: Long = 0L
  var committed: Boolean = false
  val pendingChunks: mutable.Queue[(Long, Array[Byte])] = mutable.Queue()
  var processingCallback: Option[() => Unit] = None
}

class UploadServiceImpl(quotaManager: QuotaManager, baseDir: Path) extends UploadServiceGrpc {

  private val activeSessions = new ConcurrentHashMap[String, SessionState]()

  private def resolveUserId(sessionId: String): String = {
    // In production, extracted from gRPC metadata/auth context
    sessionId.split("_").headOption.getOrElse("anonymous")
  }

  private def validateChunkIntegrity(data: Array[Byte]): Boolean = {
    data != null && data.length > 0 && data.length <= 65536
  }

  private def sanitizePath(uploadId: String): Path = {
    val sanitized = uploadId.replaceAll("[^a-zA-Z0-9\\-]", "")
    baseDir.resolve(sanitized).normalize()
  }

  private def processChunkQueue(state: SessionState): Unit = {
    while (state.pendingChunks.nonEmpty) {
      val (offset, data) = state.pendingChunks.dequeue()
      writeChunkToDisk(state, offset, data)
    }
  }

  private def writeChunkToDisk(state: SessionState, offset: Long, data: Array[Byte]): Unit = {
    // Simulate async I/O completion callback pattern
    val outputPath = state.targetPath
    if (!outputPath.startsWith(baseDir)) {
      throw new SecurityException("Path traversal detected")
    }
    Files.write(outputPath, data, java.nio.file.StandardOpenOption.CREATE,
      java.nio.file.StandardOpenOption.APPEND)
  }

  private def finalizeUpload(state: SessionState, responseObserver: StreamObserver[UploadResponse]): Unit = {
    if (!state.committed) {
      state.committed = true
      quotaManager.commit(state.userId, state.totalReceived)
      responseObserver.onNext(UploadResponse("SUCCESS", state.totalReceived))
      responseObserver.onCompleted()
      // Trigger post-upload processing hook
      state.processingCallback.foreach(cb => cb())
    }
  }

  override def streamUpload(responseObserver: StreamObserver[UploadResponse]): StreamObserver[UploadChunk] = {
    new StreamObserver[UploadChunk] {
      private var sessionState: SessionState = _

      override def onNext(chunk: UploadChunk): Unit = {
        if (sessionState == null) {
          val userId = resolveUserId(chunk.sessionId)
          val uploadId = UUID.randomUUID().toString
          val targetPath = sanitizePath(uploadId)
          sessionState = new SessionState(userId, uploadId, targetPath)
          activeSessions.put(chunk.sessionId, sessionState)
          quotaManager.initialize(userId, 104857600L) // 100MB default
        }

        if (!validateChunkIntegrity(chunk.data)) {
          responseObserver.onNext(UploadResponse("INVALID_CHUNK", 0))
          return
        }

        val state = sessionState
        // Quota check with reservation pattern
        if (!quotaManager.tryReserve(state.userId, chunk.data.length.toLong)) {
          responseObserver.onNext(UploadResponse("QUOTA_EXCEEDED", state.totalReceived))
          responseObserver.onCompleted()
          return
        }

        // Enqueue chunk for ordered processing
        state.pendingChunks.enqueue((chunk.offset, chunk.data))
        state.totalReceived += chunk.data.length

        // Process queue - this is where the reentrancy manifests
        // The callback can trigger finalizeUpload which calls commit,
        // but we haven't finished processing all chunks yet
        state.processingCallback = Some(() => {
          // Re-entrant: this callback fires during finalize,
          // but can be triggered again if another chunk arrives
          // before the stream is fully closed, allowing double-commit
          processChunkQueue(state)
        })

        processChunkQueue(state)

        if (chunk.isFinal) {
          finalizeUpload(state, responseObserver)
        }
      }

      override def onError(t: Throwable): Unit = {
        if (sessionState != null) {
          quotaManager.rollback(sessionState.userId, sessionState.totalReceived)
          activeSessions.remove(sessionState.uploadId)
        }
      }

      override def onCompleted(): Unit = {
        if (sessionState != null && !sessionState.committed) {
          finalizeUpload(sessionState, responseObserver)
        }
      }
    }
  }
}
